    )
  )

  # OLS across subjects per sample (voxelwise)
  register_reducer(
    name = "ols:voxelwise",
    fun = function(beta, var, X, z, p, df, df1, df2, opts) {
      if (is.null(X)) stop("ols:voxelwise requires X (subjects x p) in options$X or via formula", call. = FALSE)
      ret <- opts$return_cov %||% "none"
      if (!ret %in% c("none", "tri")) stop("options$return_cov must be 'none' or 'tri'", call. = FALSE)
      res <- ols_voxelwise_cpp(
        beta, X,
        return_cov_tri = identical(ret, "tri"),
        min_obs = opts$min_subjects %||% NULL
      )
      # add t and p for coefficients
      tmat <- res$coef / res$se_coef
      dfv <- matrix(res$df_res, nrow = nrow(tmat), ncol = ncol(tmat), byrow = TRUE)
      pmat <- 2 * stats::pt(-abs(tmat), df = dfv)
      res$t_coef <- tmat
      res$p_coef <- pmat
      res
    },
    requires = c("beta", "X"),
    provides = c("coef", "se_coef", "t_coef", "p_coef", "sigma2", "df_res", "n_obs", "cov_tri"),
    options_schema = list(return_cov = c("none", "tri")),
    model_contract = list(
      uses_X = TRUE,
      estimands = "linear",
      weight_mode = "unweighted",
      missingness = "samplewise",
      synthetic_variance = "allow_effect_only",
      deletion = "hat_matrix"
    ),
    diagnostics = list(
      fun = .diagnose_ols_block,
      capabilities = c("prediction", "surprise", "leverage", "coefficient_deletion", "statistic_deletion"),
      modes = "exact"
    ),
    frame_fun = .fit_frame_ols_block
  )
}

# R implementation of the voxelwise OLS kernel (no compiled override exists).
#
# Performs per-sample (voxel) listwise deletion: subjects whose effect is
# non-finite at a given sample are dropped for that sample only, and the model
# is refit on the remaining rows. Samples with fewer than `min_obs` finite
# observations (default p + 1, the minimum for a residual df) cannot be
# estimated and are returned as NA. The per-sample finite count is returned in
# `n_obs` so callers can audit effective sample size, and a single summary
# warning is emitted when any sample had non-finite subjects.
ols_voxelwise_cpp <- function(beta, X, return_cov_tri = FALSE, min_obs = NULL) {
  # beta: subjects x samples; X: subjects x p
  N <- nrow(beta); B <- ncol(beta); p <- ncol(X)
  # At least p + 1 observations are needed for a positive residual df; an
  # exactly-determined fit has no error estimate and must not be reported.
  min_obs <- if (is.null(min_obs)) p + 1L else max(as.integer(min_obs), p + 1L)
  Xt <- t(X)
  A_full <- tryCatch(solve(crossprod(X)), error = function(e) NULL)
  coef <- matrix(NA_real_, nrow = p, ncol = B)
  se   <- matrix(NA_real_, nrow = p, ncol = B)
  sigma2 <- rep(NA_real_, B)
  df_res <- rep(NA_real_, B)
  n_obs  <- rep(0L, B)
  if (return_cov_tri) {
    L <- p * (p + 1) / 2
    cov_tri <- matrix(NA_real_, nrow = L, ncol = B)
  } else {
    cov_tri <- NULL
  }
  pack_tri <- function(S, s2) {
    out <- numeric(length = p * (p + 1) / 2)
    t <- 1L
    for (i in seq_len(p)) {
      for (j in i:p) {
        out[t] <- s2 * S[i, j]
        t <- t + 1L
      }
    }
    out
  }
  # Samples with every subject finite share the full design: fit them in one
  # matrix step. The loop below handles only samples with missing subjects.
  complete <- colSums(!is.finite(beta)) == 0L
  n_obs[complete] <- N
  batch <- !is.null(A_full) && N >= min_obs && any(complete)
  if (batch) {
    idx <- which(complete)
    Yc <- beta[, idx, drop = FALSE]
    bh <- A_full %*% (Xt %*% Yc)
    s2 <- colSums((Yc - X %*% bh)^2) / (N - p)
    coef[, idx] <- bh
    se[, idx] <- sqrt(pmax(outer(diag(A_full), s2), 0))
    sigma2[idx] <- s2
    df_res[idx] <- N - p
    if (!is.null(cov_tri)) cov_tri[, idx] <- outer(pack_tri(A_full, 1), s2)
  }
  for (b in seq_len(B)) {
    if (batch && complete[b]) next
    y <- beta[, b]
    ok <- is.finite(y)
    nb <- sum(ok)
    n_obs[b] <- nb
    if (nb < min_obs) next
    if (nb == N) {
      A <- A_full; Xb <- X; Xtb <- Xt; yb <- y
    } else {
      Xb <- X[ok, , drop = FALSE]; yb <- y[ok]; Xtb <- t(Xb)
      A <- tryCatch(solve(crossprod(Xb)), error = function(e) NULL)
    }
    if (is.null(A)) next
    bh <- A %*% (Xtb %*% yb)
    r <- as.numeric(yb - Xb %*% bh)
    dff <- nb - p
    if (dff < 1) next
    s2 <- sum(r * r) / dff
    coef[, b] <- as.numeric(bh)
    se[, b] <- sqrt(pmax(diag(A) * s2, 0))
    sigma2[b] <- s2
    df_res[b] <- dff
    if (!is.null(cov_tri)) cov_tri[, b] <- pack_tri(A, s2)
  }
  n_reduced <- sum(n_obs < N)
  if (n_reduced > 0L) {
    n_dropped <- sum(n_obs < min_obs)
    warning(sprintf(
      "ols:voxelwise: %d of %d samples had non-finite subjects (per-voxel listwise deletion); %d had fewer than %d finite observations and were set to NA.",
      n_reduced, B, n_dropped, min_obs
    ), call. = FALSE)
  }
  out <- list(coef = coef, se_coef = se, sigma2 = sigma2, df_res = df_res, n_obs = as.numeric(n_obs))
  if (!is.null(cov_tri)) out$cov_tri <- cov_tri
  out
}

// [[Rcpp::depends(RcppArmadillo)]]
// [[Rcpp::plugins(cpp14)]]
// [[Rcpp::plugins(openmp)]]

#include <RcppArmadillo.h>
#ifdef _OPENMP
  #include <omp.h>
#endif

using namespace Rcpp;
using arma::mat;
using arma::vec;
using arma::uword;

inline bool finite_(double x) { return std::isfinite(x); }

// Runtime control of OpenMP threads.
//
// This is called from .onLoad, where the Rcpp namespace may not be loaded yet.
// It therefore must not touch any Rcpp runtime callable (RNGScope, or the
// `dataptr` callable used by Rcpp::as<int>): a failed callable lookup inside a
// function-local static initializer leaves its guard locked and makes every
// later Rcpp call in the session hang. Hence rng = false and a raw SEXP
// argument converted with the R API.
// [[Rcpp::export(rng = false)]]
void set_omp_threads(SEXP n) {
  const int nn = Rf_asInteger(n);
#ifdef _OPENMP
  if (nn != NA_INTEGER && nn > 0) {
    omp_set_num_threads(nn);
  }
#else
  (void)nn; // suppress unused warning when OpenMP is not enabled
#endif
}

// ----- Fixed-Effects meta (beta/var) -----

// tail: 0 = two.sided, 1 = less, 2 = greater
// [[Rcpp::export]]
Rcpp::List meta_fe_cpp(const arma::mat& beta, const arma::mat& var,
                       const int min_subj = 2,
                       const double eps = 1e-12,
                       const int tail = 0) {
  const uword S = beta.n_rows;
  const uword B = beta.n_cols;
  NumericVector mu(B), var_mu(B), se_mu(B), z(B), p(B), Q(B), I2(B);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double sw = 0.0, wy = 0.0;
    int k = 0;

    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        sw += w; wy += w * y; ++k;
      }
    }
    if (k < min_subj || sw <= 0.0) {
      mu[b] = var_mu[b] = se_mu[b] = z[b] = p[b] = Q[b] = I2[b] = NA_REAL;
      continue;
    }

    double mu_b = wy / sw;
    double var_b = 1.0 / sw;
    double se_b  = std::sqrt(var_b);

    double Qb = 0.0;
    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        double r = y - mu_b;
        Qb += w * r * r;
      }
    }
    double I2b = (Qb > eps) ? std::max(0.0, (Qb - (k - 1.0)) / Qb) : 0.0;
    double zb = (se_b > 0.0) ? (mu_b / se_b) : NA_REAL;
    double pb = NA_REAL;
    if (finite_(zb)) {
      if (tail == 0)      pb = 2.0 * R::pnorm(-std::fabs(zb), 0.0, 1.0, 1, 0);
      else if (tail == 1) pb = R::pnorm(zb, 0.0, 1.0, 1, 0);
      else                pb = R::pnorm(zb, 0.0, 1.0, 0, 0);
    }

    mu[b]     = mu_b;
    var_mu[b] = var_b;
    se_mu[b]  = se_b;
    z[b]      = zb;
    p[b]      = pb;
    Q[b]      = Qb;
    I2[b]     = I2b;
  }

  return Rcpp::List::create(
    _["beta_g"] = mu,
    _["var_g"]  = var_mu,
    _["se_g"]   = se_mu,
    _["z_g"]    = z,
    _["p_g"]    = p,
    _["Q"]      = Q,
    _["I2"]     = I2
  );
}

// ----- Random-Effects meta (DL tau2) -----

// [[Rcpp::export]]
Rcpp::List meta_re_dl_cpp(const arma::mat& beta, const arma::mat& var,
                          const int min_subj = 2,
                          const double eps = 1e-12,
                          const int tail = 0) {
  const uword S = beta.n_rows;
  const uword B = beta.n_cols;
  NumericVector mu(B), var_mu(B), se_mu(B), z(B), p(B), Q(B), I2(B), tau2(B);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double sw = 0.0, wy = 0.0, sum_w2 = 0.0;
    int k = 0;

    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        sw += w; wy += w * y; sum_w2 += w * w; ++k;
      }
    }
    if (k < min_subj || sw <= 0.0) {
      mu[b] = var_mu[b] = se_mu[b] = z[b] = p[b] = Q[b] = I2[b] = tau2[b] = NA_REAL;
      continue;
    }
    double mu_fe = wy / sw;

    double Qb = 0.0;
    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        double r = y - mu_fe;
        Qb += w * r * r;
      }
    }
    double C = sw - (sum_w2 / sw);
    double t2 = std::max(0.0, (Qb - (k - 1.0)) / std::max(C, eps));

    double sws = 0.0, wys = 0.0;
    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / (std::max(v, eps) + t2);
        sws += w; wys += w * y;
      }
    }
    if (sws <= 0.0) {
      mu[b] = var_mu[b] = se_mu[b] = z[b] = p[b] = Q[b] = I2[b] = tau2[b] = NA_REAL;
      continue;
    }
    double mu_re = wys / sws;
    double var_re = 1.0 / sws;
    double se_re  = std::sqrt(var_re);

    double I2b = (Qb > eps) ? std::max(0.0, (Qb - (k - 1.0)) / Qb) : 0.0;

    double zb = (se_re > 0.0) ? (mu_re / se_re) : NA_REAL;
    double pb = NA_REAL;
    if (finite_(zb)) {
      if (tail == 0)      pb = 2.0 * R::pnorm(-std::fabs(zb), 0.0, 1.0, 1, 0);
      else if (tail == 1) pb = R::pnorm(zb, 0.0, 1.0, 1, 0);
      else                pb = R::pnorm(zb, 0.0, 1.0, 0, 0);
    }

    mu[b]     = mu_re;
    var_mu[b] = var_re;
    se_mu[b]  = se_re;
    z[b]      = zb;
    p[b]      = pb;
    Q[b]      = Qb;
    I2[b]     = I2b;
    tau2[b]   = t2;
  }

  return Rcpp::List::create(
    _["beta_g"] = mu,
    _["var_g"]  = var_mu,
    _["se_g"]   = se_mu,
    _["z_g"]    = z,
    _["p_g"]    = p,
    _["tau2"]   = tau2,
    _["Q"]      = Q,
    _["I2"]     = I2
  );
}

// ----- Fixed-Effects meta-regression (WLS) -----

// [[Rcpp::export]]
Rcpp::List meta_fe_reg_cpp(const arma::mat& beta, const arma::mat& var,
                           const arma::mat& X,
                           const int min_subj = 2,
                           const double eps = 1e-12) {
  const uword S = beta.n_rows;
  const uword B = beta.n_cols;
  const uword p = X.n_cols;

  arma::mat coef(p, B, arma::fill::value(NA_REAL));
  arma::mat se  (p, B, arma::fill::value(NA_REAL));
  NumericVector Q(B), df_res(B);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    arma::mat G(p, p, arma::fill::zeros);
    arma::vec g(p, arma::fill::zeros);
    int k = 0;

    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        arma::rowvec xi = X.row(i);
        if (!xi.is_finite()) continue;
        G  += w * (xi.t() * xi);
        g  += w * (xi.t() * y);
        ++k;
      }
    }
    if (k < std::max<int>(min_subj, p + 1)) { Q[b] = df_res[b] = NA_REAL; continue; }
    arma::mat A;
    bool ok = arma::inv_sympd(A, G);
    if (!ok) { Q[b] = df_res[b] = NA_REAL; continue; }
    arma::vec bh = A * g;
    double Qb = 0.0;
    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        arma::rowvec xi = X.row(i);
        if (!xi.is_finite()) continue;
        double r = y - arma::dot(xi, bh);
        Qb += w * r * r;
      }
    }
    coef.col(b) = bh;
    for (uword j = 0; j < p; ++j) se(j, b) = std::sqrt(std::max(A(j, j), 0.0));
    Q[b] = Qb; df_res[b] = static_cast<double>(k - static_cast<int>(p));
  }

  return Rcpp::List::create(
    _["coef"]   = coef,
    _["se_coef"] = se,
    _["Q"]      = Q,
    _["df_res"]  = df_res
  );
}

// ----- Random-Effects meta-regression (DL tau2) -----

// [[Rcpp::export]]
Rcpp::List meta_re_reg_dl_cpp(const arma::mat& beta, const arma::mat& var,
                              const arma::mat& X,
                              const int min_subj = 2,
                              const double eps = 1e-12) {
  const uword S = beta.n_rows;
  const uword B = beta.n_cols;
  const uword p = X.n_cols;

  arma::mat coef(p, B, arma::fill::value(NA_REAL));
  arma::mat se  (p, B, arma::fill::value(NA_REAL));
  NumericVector tau2(B, NA_REAL), Q(B, NA_REAL), df_res(B, NA_REAL);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    arma::mat G(p, p, arma::fill::zeros);
    arma::vec g(p, arma::fill::zeros);
    std::vector<double> w_save; w_save.resize(S, 0.0);
    int k = 0;

    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / std::max(v, eps);
        w_save[i] = w;
        arma::rowvec xi = X.row(i);
        if (!xi.is_finite()) { w_save[i] = 0.0; continue; }
        G += w * (xi.t() * xi);
        g += w * (xi.t() * y);
        ++k;
      } else {
        w_save[i] = 0.0;
      }
    }
    if (k < std::max<int>(min_subj, p + 1)) { tau2[b] = Q[b] = df_res[b] = NA_REAL; continue; }
    if (arma::rank(G) < p) { tau2[b] = Q[b] = df_res[b] = NA_REAL; continue; }
    arma::mat A;
    bool ok = arma::inv_sympd(A, G);
    if (!ok) { tau2[b] = Q[b] = df_res[b] = NA_REAL; continue; }
    arma::vec bh_fe = A * g;

    double Qb = 0.0, sw = 0.0, trace_correction = 0.0;
    for (uword i = 0; i < S; ++i) {
      double w = w_save[i];
      if (w <= 0.0) continue;
      sw += w;
      double r = beta(i, b) - arma::dot(X.row(i), bh_fe);
      Qb += w * r * r;
      double xAx = arma::as_scalar(X.row(i) * A * X.row(i).t());
      trace_correction += w * w * xAx;
    }
    // P = W - W X (X' W X)^-1 X' W, hence
    // tr(P) = sum(w_i) - sum(w_i^2 x_i' A x_i).
    double C = sw - trace_correction;
    double dfb = static_cast<double>(k - static_cast<int>(p));
    if (!finite_(C) || C <= 0.0) {
      tau2[b] = Q[b] = df_res[b] = NA_REAL;
      continue;
    }
    double t2 = std::max(0.0, (Qb - dfb) / C);

    arma::mat Gs(p, p, arma::fill::zeros);
    arma::vec gs(p, arma::fill::zeros);
    for (uword i = 0; i < S; ++i) {
      double y = beta(i, b);
      double v = var(i, b);
      if (finite_(y) && finite_(v) && v > 0.0) {
        double w = 1.0 / (std::max(v, eps) + t2);
        arma::rowvec xi = X.row(i);
        if (!xi.is_finite()) continue;
        Gs += w * (xi.t() * xi);
        gs += w * (xi.t() * y);
      }
    }
    arma::mat As;
    ok = arma::inv_sympd(As, Gs);
    if (!ok) { tau2[b] = Q[b] = df_res[b] = NA_REAL; continue; }
    arma::vec bh = As * gs;
    coef.col(b) = bh;
    for (uword j = 0; j < p; ++j) se(j, b) = std::sqrt(std::max(As(j, j), 0.0));
    tau2[b] = t2; Q[b] = Qb; df_res[b] = dfb;
  }

  return Rcpp::List::create(
    _["coef"]    = coef,
    _["se_coef"] = se,
    _["tau2"]    = tau2,
    _["Q"]       = Q,
    _["df_res"]  = df_res
  );
}

// ----- Stouffer (Z-combiner) -----

// [[Rcpp::export]]
Rcpp::List stouffer_combine_cpp(const arma::mat& z,
                                Rcpp::Nullable<Rcpp::NumericVector> weights = R_NilValue,
                                const int min_subj = 1) {
  const uword S = z.n_rows, B = z.n_cols;
  NumericVector Z(B), p(B);

  std::vector<double> w(S, 1.0);
  if (weights.isNotNull()) {
    NumericVector ww(weights);
    if (ww.size() == S) {
      for (uword i = 0; i < S; ++i) w[i] = ww[i];
    }
  }

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double num = 0.0, den2 = 0.0; int k = 0;
    for (uword i = 0; i < S; ++i) {
      double zi = z(i, b);
      if (finite_(zi)) { num += w[i] * zi; den2 += w[i] * w[i]; ++k; }
    }
    if (k < min_subj || den2 <= 0.0) { Z[b] = p[b] = NA_REAL; continue; }
    double Zb = num / std::sqrt(den2);
    Z[b] = Zb;
    p[b] = 2.0 * R::pnorm(-std::fabs(Zb), 0.0, 1.0, 1, 0);
  }
  return Rcpp::List::create(_["z_g"] = Z, _["p_g"] = p);
}

// ----- Fisher (p-combiner) -----

inline double clamp_p(double x) {
  if (!finite_(x)) return NA_REAL;
  if (x <= 0.0)    return 1e-300;
  if (x >= 1.0)    return 1.0 - 1e-16;
  return x;
}

// [[Rcpp::export]]
Rcpp::List fisher_combine_cpp(const arma::mat& pmat, const int min_subj = 1) {
  const uword S = pmat.n_rows, B = pmat.n_cols;
  NumericVector stat(B), df(B), p(B);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double X2 = 0.0; int k = 0;
    for (uword i = 0; i < S; ++i) {
      double pi = clamp_p(pmat(i, b));
      if (finite_(pi)) { X2 += -2.0 * std::log(pi); ++k; }
    }
    if (k < min_subj) { stat[b]=df[b]=p[b]=NA_REAL; continue; }
    double dfb = 2.0 * k;
    double pb  = R::pchisq(X2, dfb, /*lower_tail*/0, /*log_p*/0);
    stat[b] = X2; df[b] = dfb; p[b] = pb;
  }
  return Rcpp::List::create(_["chi2"] = stat, _["df"] = df, _["p_g"] = p);
}

// ----- Lancaster (weighted Fisher) -----

// [[Rcpp::export]]
Rcpp::List lancaster_combine_cpp(const arma::mat& pmat,
                                 const Rcpp::IntegerVector dfw,
                                 const int min_subj = 1) {
  const uword S = pmat.n_rows, B = pmat.n_cols;
  NumericVector stat(B), df(B), p(B);

  if (static_cast<uword>(dfw.size()) != S)
    stop("dfw length must equal number of subjects (rows of p).");

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double X2 = 0.0; int df_sum = 0; int k = 0;
    for (uword i = 0; i < S; ++i) {
      double pi = clamp_p(pmat(i, b));
      if (finite_(pi)) {
        int wi = std::max(dfw[i], 1);
        // Upper-tail quantile: qchisq(1 - p) overflows to Inf once 1 - p rounds to 1.
        double chi_i = R::qchisq(pi, 2.0 * wi, /*lower_tail*/0, /*log_p*/0);
        X2 += chi_i; df_sum += 2 * wi; ++k;
      }
    }
    if (k < min_subj || df_sum <= 0) { stat[b]=df[b]=p[b]=NA_REAL; continue; }
    double pb = R::pchisq(X2, (double)df_sum, /*lower_tail*/0, /*log_p*/0);
    stat[b] = X2; df[b] = (double)df_sum; p[b] = pb;
  }
  return Rcpp::List::create(_["chi2"] = stat, _["df"] = df, _["p_g"] = p);
}

// ----- Permutation tests ----------------------------------------------------

inline double perm_tail_p(const double obs, const double null_stat, const int tail) {
  if (!finite_(obs) || !finite_(null_stat)) return 0.0;
  if (tail == 1) return null_stat <= obs ? 1.0 : 0.0;       // less
  if (tail == 2) return null_stat >= obs ? 1.0 : 0.0;       // greater
  return std::fabs(null_stat) >= std::fabs(obs) ? 1.0 : 0.0; // two.sided
}

// Tail-specific "extremeness" of a statistic: larger is more extreme in the
// direction of the alternative. Used for max-statistic FWER control.
inline double perm_tail_extreme(const double t, const int tail) {
  if (tail == 1) return -t;          // less
  if (tail == 2) return t;           // greater
  return std::fabs(t);               // two.sided
}

inline double mean_from_sums(const double sum, const int n) {
  return n > 0 ? sum / static_cast<double>(n) : NA_REAL;
}

inline double t_onesample_from_sums(const double sum, const double sumsq, const int n) {
  if (n < 2) return NA_REAL;
  const double mean = sum / static_cast<double>(n);
  double var = (sumsq - static_cast<double>(n) * mean * mean) / static_cast<double>(n - 1);
  if (var < 0.0 && var > -1e-10) var = 0.0;
  if (var <= 0.0 || !finite_(var)) return NA_REAL;
  return mean / std::sqrt(var / static_cast<double>(n));
}

inline double t_twosample_from_sums(const double sum0, const double sumsq0, const int n0,
                                    const double sum1, const double sumsq1, const int n1,
                                    const bool welch) {
  if (n0 < 2 || n1 < 2) return NA_REAL;
  const double m0 = sum0 / static_cast<double>(n0);
  const double m1 = sum1 / static_cast<double>(n1);
  double v0 = (sumsq0 - static_cast<double>(n0) * m0 * m0) / static_cast<double>(n0 - 1);
  double v1 = (sumsq1 - static_cast<double>(n1) * m1 * m1) / static_cast<double>(n1 - 1);
  if (v0 < 0.0 && v0 > -1e-10) v0 = 0.0;
  if (v1 < 0.0 && v1 > -1e-10) v1 = 0.0;
  if (!finite_(v0) || !finite_(v1)) return NA_REAL;
  double se2;
  if (welch) {
    se2 = v0 / static_cast<double>(n0) + v1 / static_cast<double>(n1);
  } else {
    const double sp2 = ((n0 - 1.0) * v0 + (n1 - 1.0) * v1) / static_cast<double>(n0 + n1 - 2);
    se2 = sp2 * (1.0 / static_cast<double>(n0) + 1.0 / static_cast<double>(n1));
  }
  if (se2 <= 0.0 || !finite_(se2)) return NA_REAL;
  return (m1 - m0) / std::sqrt(se2);
}

// sign_mat is n_perm x subjects with entries -1/+1. The observed statistic is
// always computed from the unpermuted data. When skip_first is true, row 1 of
// sign_mat is the identity relabelling and is excluded from the null set so the
// observed statistic is not double counted. p-values use
// p = (1 + #{null >= obs}) / (1 + n_null), with "more extreme" defined by the
// requested tail (two-sided |t|, greater t, less -t), also for the max-stat FWER.
// [[Rcpp::export]]
Rcpp::List perm_onesample_t_cpp(const arma::mat& beta,
                                const arma::imat& sign_mat,
                                const int tail = 0,
                                const int min_subj = 2,
                                const bool skip_first = false) {
  const uword S = beta.n_rows, B = beta.n_cols;
  const uword P = sign_mat.n_rows;
  if (sign_mat.n_cols != S) stop("sign_mat column count must equal number of subjects.");
  const uword first = (skip_first && P > 0) ? 1 : 0;
  const double n_null = static_cast<double>(P - first);

  NumericVector estimate(B), se(B), stat(B), df(B), p_perm(B), p_fwer(B);
  NumericVector max_null(P);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long pp = 0; pp < static_cast<long>(P); ++pp) {
    double max_ext = R_NegInf;
    for (uword b = 0; b < B; ++b) {
      double sum = 0.0, sumsq = 0.0;
      int n = 0;
      for (uword i = 0; i < S; ++i) {
        const double y = beta(i, b);
        if (!finite_(y)) continue;
        const double yp = static_cast<double>(sign_mat(pp, i)) * y;
        sum += yp;
        sumsq += yp * yp;
        ++n;
      }
      if (n < min_subj) continue;
      const double tp = t_onesample_from_sums(sum, sumsq, n);
      if (finite_(tp)) max_ext = std::max(max_ext, perm_tail_extreme(tp, tail));
    }
    max_null[pp] = max_ext;
  }

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double sum = 0.0, sumsq = 0.0;
    int n = 0;
    for (uword i = 0; i < S; ++i) {
      const double y = beta(i, b);
      if (!finite_(y)) continue;
      sum += y;
      sumsq += y * y;
      ++n;
    }
    if (n < min_subj) {
      estimate[b] = se[b] = stat[b] = df[b] = p_perm[b] = p_fwer[b] = NA_REAL;
      continue;
    }
    const double mean = mean_from_sums(sum, n);
    double var = (sumsq - static_cast<double>(n) * mean * mean) / static_cast<double>(n - 1);
    if (var < 0.0 && var > -1e-10) var = 0.0;
    const double seb = (var > 0.0 && finite_(var)) ? std::sqrt(var / static_cast<double>(n)) : NA_REAL;
    const double tobs = t_onesample_from_sums(sum, sumsq, n);
    estimate[b] = mean;
    se[b] = seb;
    stat[b] = tobs;
    df[b] = static_cast<double>(n - 1);
    if (!finite_(tobs)) {
      p_perm[b] = p_fwer[b] = NA_REAL;
      continue;
    }
    const double obs_ext = perm_tail_extreme(tobs, tail);
    double count = 0.0, count_fwer = 0.0;
    for (uword pp = first; pp < P; ++pp) {
      double psum = 0.0, psumsq = 0.0;
      int pn = 0;
      for (uword i = 0; i < S; ++i) {
        const double y = beta(i, b);
        if (!finite_(y)) continue;
        const double yp = static_cast<double>(sign_mat(pp, i)) * y;
        psum += yp;
        psumsq += yp * yp;
        ++pn;
      }
      const double tnull = t_onesample_from_sums(psum, psumsq, pn);
      count += perm_tail_p(tobs, tnull, tail);
      if (max_null[pp] >= obs_ext) count_fwer += 1.0;
    }
    p_perm[b] = (count + 1.0) / (n_null + 1.0);
    p_fwer[b] = (count_fwer + 1.0) / (n_null + 1.0);
  }

  return Rcpp::List::create(
    _["beta_g"] = estimate,
    _["se_g"] = se,
    _["t_g"] = stat,
    _["df"] = df,
    _["p_perm"] = p_perm,
    _["p_fwer"] = p_fwer,
    _["max_t_null"] = max_null
  );
}

// group_mat is n_perm x subjects with entries 0/1; group is the observed 0/1
// labelling (length = subjects). The observed effect
// mean(group == 1) - mean(group == 0) is always computed from `group`, never
// from a row of group_mat. When skip_first is true, row 1 of group_mat is the
// identity relabelling and is excluded from the null set.
// p = (1 + #{null >= obs}) / (1 + n_null).
// [[Rcpp::export]]
Rcpp::List perm_twosample_t_cpp(const arma::mat& beta,
                                const arma::imat& group_mat,
                                const Rcpp::IntegerVector& group,
                                const int tail = 0,
                                const bool welch = true,
                                const int min_group = 2,
                                const bool skip_first = false) {
  const uword S = beta.n_rows, B = beta.n_cols;
  const uword P = group_mat.n_rows;
  if (group_mat.n_cols != S) stop("group_mat column count must equal number of subjects.");
  if (static_cast<uword>(group.size()) != S) stop("group length must equal number of subjects.");
  const uword first = (skip_first && P > 0) ? 1 : 0;
  const double n_null = static_cast<double>(P - first);
  std::vector<int> g(S);
  for (uword i = 0; i < S; ++i) g[i] = group[i];

  NumericVector estimate(B), se(B), stat(B), df(B), p_perm(B), p_fwer(B);
  NumericVector max_null(P);

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long pp = 0; pp < static_cast<long>(P); ++pp) {
    double max_ext = R_NegInf;
    for (uword b = 0; b < B; ++b) {
      double sum0 = 0.0, sum1 = 0.0, sumsq0 = 0.0, sumsq1 = 0.0;
      int n0 = 0, n1 = 0;
      for (uword i = 0; i < S; ++i) {
        const double y = beta(i, b);
        if (!finite_(y)) continue;
        if (group_mat(pp, i) == 1) {
          sum1 += y; sumsq1 += y * y; ++n1;
        } else {
          sum0 += y; sumsq0 += y * y; ++n0;
        }
      }
      if (n0 < min_group || n1 < min_group) continue;
      const double tp = t_twosample_from_sums(sum0, sumsq0, n0, sum1, sumsq1, n1, welch);
      if (finite_(tp)) max_ext = std::max(max_ext, perm_tail_extreme(tp, tail));
    }
    max_null[pp] = max_ext;
  }

  #ifdef _OPENMP
  #pragma omp parallel for schedule(static)
  #endif
  for (long b = 0; b < static_cast<long>(B); ++b) {
    double sum0 = 0.0, sum1 = 0.0, sumsq0 = 0.0, sumsq1 = 0.0;
    int n0 = 0, n1 = 0;
    for (uword i = 0; i < S; ++i) {
      const double y = beta(i, b);
      if (!finite_(y)) continue;
      if (g[i] == 1) {
        sum1 += y; sumsq1 += y * y; ++n1;
      } else {
        sum0 += y; sumsq0 += y * y; ++n0;
      }
    }
    if (n0 < min_group || n1 < min_group) {
      estimate[b] = se[b] = stat[b] = df[b] = p_perm[b] = p_fwer[b] = NA_REAL;
      continue;
    }
    const double m0 = sum0 / static_cast<double>(n0);
    const double m1 = sum1 / static_cast<double>(n1);
    double v0 = (sumsq0 - static_cast<double>(n0) * m0 * m0) / static_cast<double>(n0 - 1);
    double v1 = (sumsq1 - static_cast<double>(n1) * m1 * m1) / static_cast<double>(n1 - 1);
    if (v0 < 0.0 && v0 > -1e-10) v0 = 0.0;
    if (v1 < 0.0 && v1 > -1e-10) v1 = 0.0;
    double se2;
    double dfb;
    if (welch) {
      const double a = v0 / static_cast<double>(n0);
      const double c = v1 / static_cast<double>(n1);
      se2 = a + c;
      const double den = (a * a) / static_cast<double>(n0 - 1) + (c * c) / static_cast<double>(n1 - 1);
      dfb = den > 0.0 ? (se2 * se2) / den : NA_REAL;
    } else {
      const double sp2 = ((n0 - 1.0) * v0 + (n1 - 1.0) * v1) / static_cast<double>(n0 + n1 - 2);
      se2 = sp2 * (1.0 / static_cast<double>(n0) + 1.0 / static_cast<double>(n1));
      dfb = static_cast<double>(n0 + n1 - 2);
    }
    const double tobs = t_twosample_from_sums(sum0, sumsq0, n0, sum1, sumsq1, n1, welch);
    estimate[b] = m1 - m0;
    se[b] = se2 > 0.0 ? std::sqrt(se2) : NA_REAL;
    stat[b] = tobs;
    df[b] = dfb;
    if (!finite_(tobs)) {
      p_perm[b] = p_fwer[b] = NA_REAL;
      continue;
    }
    const double obs_ext = perm_tail_extreme(tobs, tail);
    double count = 0.0, count_fwer = 0.0;
    for (uword pp = first; pp < P; ++pp) {
      double psum0 = 0.0, psum1 = 0.0, psumsq0 = 0.0, psumsq1 = 0.0;
      int pn0 = 0, pn1 = 0;
      for (uword i = 0; i < S; ++i) {
        const double y = beta(i, b);
        if (!finite_(y)) continue;
        if (group_mat(pp, i) == 1) {
          psum1 += y; psumsq1 += y * y; ++pn1;
        } else {
          psum0 += y; psumsq0 += y * y; ++pn0;
        }
      }
      const double tnull = t_twosample_from_sums(psum0, psumsq0, pn0, psum1, psumsq1, pn1, welch);
      count += perm_tail_p(tobs, tnull, tail);
      if (max_null[pp] >= obs_ext) count_fwer += 1.0;
    }
    p_perm[b] = (count + 1.0) / (n_null + 1.0);
    p_fwer[b] = (count_fwer + 1.0) / (n_null + 1.0);
  }

  return Rcpp::List::create(
    _["beta_g"] = estimate,
    _["se_g"] = se,
    _["t_g"] = stat,
    _["df"] = df,
    _["p_perm"] = p_perm,
    _["p_fwer"] = p_fwer,
    _["max_t_null"] = max_null
  );
}
